void point2Streak( geometryInS inputs[1], bool isCulled, 
    float lineWidth, float tailSize, float tailFade, int normalDir, 
    float4x4 worldViewProj, float2 screenSize, float4x4 viewProjInverse, 
    inout TriangleStream<geometryInS> outStream ) 
{ 
    if( isCulled ) return; 

    geometryInS outS = inputs[0]; 
    float4 length = mul( float4( tailSize * outS.Nw, 0.0f ), worldViewProj ); 
    float2 dir = normalize(length.xy); 
    float4 width = lineWidth  * outS.Pc.w * float4(float2(dir.y, -dir.x)/screenSize, 0.0f, 0.0f);  

    float3 widthInWorld = mul(width, viewProjInverse).xyz; 
    float3 lengthInWorld = mul(length, viewProjInverse).xyz; 

    outS.Pc = inputs[0].Pc + width; 
    outS.Pw = inputs[0].Pw + widthInWorld; 
    outS.UVFromGS = float3(1.0, 0.0, 0.0); 
    if(normalDir == 2) outS.Nw = outS.Vw; 
    else if(normalDir == 3) outS.Nw = -outS.Nw; 
    outStream.Append( outS ); 
    outS.Pc = inputs[0].Pc - width; 
    outS.Pw = inputs[0].Pw - widthInWorld; 
    outStream.Append( outS ); 
    outS.Pc = inputs[0].Pc - length + width; 
    outS.Pw = inputs[0].Pw - lengthInWorld + widthInWorld; 
    outS.UVFromGS = float3(tailFade, 0.0, 0.0); 
    outStream.Append( outS ); 
    outS.Pc = inputs[0].Pc - length - width; 
    outS.Pw = inputs[0].Pw - lengthInWorld - widthInWorld; 
    outStream.Append( outS ); 
    outStream.RestartStrip(); 
}


void point2Streak( AttribArray<geometryInS> inputs, bool isCulled, 
    float lineWidth, float tailSize, float tailFade, int normalDir, 
    float4x4 worldViewProj, float2 screenSize, float4x4 viewProjInverse ) 
{ 
    if( isCulled ) return; 

    geometryInS outS = inputs[0]; 
    float4 length = mul( worldViewProj, float4( tailSize * outS.Nw, 0.0f ) ); 
    float2 dir = normalize(length.xy); 
    float4 width = lineWidth  * outS.Pc.w * float4(float2(dir.y, -dir.x)/screenSize, 0.0f, 0.0f);  

    float3 widthInWorld = mul(viewProjInverse, width).xyz; 
    float3 lengthInWorld = mul(viewProjInverse, length).xyz; 

    outS.Pc = inputs[0].Pc + width; 
    outS.Pw = inputs[0].Pw + widthInWorld; 
    outS.UVFromGS = float3(1.0, 0.0, 0.0); 
    if(normalDir == 2) outS.Nw = outS.Vw; 
    else if(normalDir == 3) outS.Nw = -outS.Nw; 
    emitVertex( outS ); 
    outS.Pc = inputs[0].Pc - width; 
    outS.Pw = inputs[0].Pw - widthInWorld; 
    emitVertex( outS ); 
    outS.Pc = inputs[0].Pc - length + width; 
    outS.Pw = inputs[0].Pw - lengthInWorld + widthInWorld; 
    outS.UVFromGS = float3(tailFade, 0.0, 0.0); 
    emitVertex( outS ); 
    outS.Pc = inputs[0].Pc - length - width; 
    outS.Pw = inputs[0].Pw - lengthInWorld - widthInWorld; 
    emitVertex( outS ); 
    restartStrip(); 
}


void point2Streak(  bool isCulled, 
    float lineWidth, float tailSize, float tailFade, int normalDir, 
    mat4x4 worldViewProj, vec2 screenSize, mat4x4 viewProjInverse ) 
{ 
    if( isCulled ) return; 

    GEO_OUT_struct outS = copyFromGEO_IN(0); 
    vec4 length = mul( worldViewProj, vec4( tailSize * outS.Nw, 0.0f ) ); 
    vec2 dir = normalize(length.xy); 
    vec4 width = lineWidth  * outS.Pc.w * vec4(vec2(dir.y, -dir.x)/screenSize, 0.0f, 0.0f);  

    vec3 widthInWorld = mul(viewProjInverse, width).xyz; 
    vec3 lengthInWorld = mul(viewProjInverse, length).xyz; 

    outS.Pc = gl_in[0].gl_Position + width; 
    outS.Pw = GEO_IN[0].Pw + widthInWorld; 
    outS.UVFromGS = vec3(1.0, 0.0, 0.0); 
    if(normalDir == 2) outS.Nw = outS.Vw; 
    else if(normalDir == 3) outS.Nw = -outS.Nw; 
    EmitGeoStruct( outS ); 
    outS.Pc = gl_in[0].gl_Position - width; 
    outS.Pw = GEO_IN[0].Pw - widthInWorld; 
    EmitGeoStruct( outS ); 
    outS.Pc = gl_in[0].gl_Position - length + width; 
    outS.Pw = GEO_IN[0].Pw - lengthInWorld + widthInWorld; 
    outS.UVFromGS = vec3(tailFade, 0.0, 0.0); 
    EmitGeoStruct( outS ); 
    outS.Pc = gl_in[0].gl_Position - length - width; 
    outS.Pw = GEO_IN[0].Pw - lengthInWorld - widthInWorld; 
    EmitGeoStruct( outS ); 
    EndPrimitive(); 
}


void point2Streak( geometryInS inputs[1], bool isCulled, 
    float lineWidth, float tailSize, float tailFade, int normalDir, 
    float4x4 worldViewProj, float2 screenSize, float4x4 viewProjInverse, 
    inout TriangleStream<geometryInS> outStream ) 
{ 
    if( isCulled ) return; 

    geometryInS outS = inputs[0]; 
    float4 length = mul( float4( tailSize * outS.Nw, 0.0f ), worldViewProj ); 
    float2 dir = normalize(length.xy); 
    float4 width = lineWidth  * outS.Pc.w * float4(float2(dir.y, -dir.x)/screenSize, 0.0f, 0.0f);  

    float3 widthInWorld = mul(width, viewProjInverse).xyz; 
    float3 lengthInWorld = mul(length, viewProjInverse).xyz; 

    outS.Pc = inputs[0].Pc + width; 
    outS.Pw = inputs[0].Pw + widthInWorld; 
    outS.UVFromGS = float3(1.0, 0.0, 0.0); 
    if(normalDir == 2) outS.Nw = outS.Vw; 
    else if(normalDir == 3) outS.Nw = -outS.Nw; 
    outStream.Append( outS ); 
    outS.Pc = inputs[0].Pc - width; 
    outS.Pw = inputs[0].Pw - widthInWorld; 
    outStream.Append( outS ); 
    outS.Pc = inputs[0].Pc - length + width; 
    outS.Pw = inputs[0].Pw - lengthInWorld + widthInWorld; 
    outS.UVFromGS = float3(tailFade, 0.0, 0.0); 
    outStream.Append( outS ); 
    outS.Pc = inputs[0].Pc - length - width; 
    outS.Pw = inputs[0].Pw - lengthInWorld - widthInWorld; 
    outStream.Append( outS ); 
    outStream.RestartStrip(); 
}
